package lumiknit.app.hwik.comp_mainview

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.pager.VerticalPager
import androidx.compose.foundation.pager.rememberPagerState
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

// MainPager is a composable function that creates a vertical pager with the specified number of pages.
// It currently does not display any content in the pages.
@Composable
fun Pager(
	modifier: Modifier = Modifier,
	pageCount: Int,
) {
	val pagerState = rememberPagerState(pageCount = {
		10
	})
	val imageURL =
		"data:image/webp;base64," // Placeholder for image URL
	VerticalPager(
		state = pagerState,
	) { page ->
		ArticleView(
			modifier = Modifier
				.fillMaxSize()
				.padding(4.dp, 0.dp),
		)
	}
}